option_result_eager.source:
let mut calls:u64=0;
fn fallback()->u8 { calls=calls+1; return 9; }
fn main()->i32 {
    let some:Option<u8>=Option.Some(7);
    let none:Option<u8>=Option.None();
    let ok:Result<u8,string>=Result.Ok(3);
    let err:Result<u8,string>=Result.Err("bad");
    let ok_state=ok.is_ok();let err_state=err.is_err();
    let a=ok.unwrap_or(fallback());
    let b=err.unwrap_or(fallback());
    printf("%ld %ld %ld %ld %ld %ld %ld %ld\n",
           some.is_some(),none.is_some(),some.unwrap(),ok_state,err_state,a,b,calls);
    return 0;
}

vec_primitive_lifecycle.source:
fn main()->i32 {
    let mut v:Vec<u8>=Vec.new();
    v.push(1); v.push(2); v.push(3);
    let mut copy:Vec<u8>=Vec.new();let mut i:u64=0;while i<v.len(){copy.push(^v.get(i));i=i+1;} v.set(0,9);
    let first=^v.get(0); let last=v.pop().unwrap();
    v.clear();
    printf("%ld %ld %ld %ld %ld\n",first,last,v.length(),^copy.get(0),v.pop().is_err());
    v.drop(); copy.drop();
    return 0;
}

vec_managed_children.source:
struct Item { pub value:u64, }
fn main()->i32 {
    let mut v:Vec<Item>=Vec.new(); v.push(Item{value:7});
    let first=Item{value:v.get(0).value};let mut copy:Vec<Item>=Vec.new();copy.push(Item{value:first.value});
    v.set(0,Item{value:9});
    printf("%ld %ld %ld\n",first.value,copy.get(0).value,v.get(0).value);
    v.clear(); v.drop();
    printf("%ld %ld\n",first.value,copy.get(0).value);
    copy.drop(); return 0;
}

