raw_owned_text_and_equality.source:
fn main()->i32 {
    let part="fishy".substring(0,4);
    let empty="fish".substring(3,1);
    let a="fi".concat("sh"); let b="fi".concat("sh");
    printf("%s %ld %ld %ld\n",part,empty.len(),a.equals(b),a==b);
    free(part); free(empty); free(a); free(b);
    return 0;
}

split_nonempty_owned_pieces.source:
fn main()->i32 {
    let source="a".concat(",,b,"); let mut pieces=source.split(",");
    printf("%ld ",^pieces.get(0)!=source);
    let mut i:u64=0;
    while i<pieces.length() {
        let piece=^pieces.get(i); printf("<%s>",piece); free(piece); i=i+1;
    }
    printf("|%ld\n",pieces.length());
    pieces.drop(); free(source); return 0;
}

split_empty_borrows_source.source:
fn main()->i32 {
    let source="a".concat("b"); let mut pieces=source.split("");
    printf("%ld %ld %s\n",pieces.length(),^pieces.get(0)==source,^pieces.get(0));
    // The token is source itself: only the Vec backing store is new here.
    pieces.drop(); free(source); return 0;
}

