fn main()->i32 {
    let ordinary=read_line(16); let blank=read_line(16);
    let bounded=read_line(4); let following=read_line(16); let eof=read_line(16);
    printf("%s|%ld|%s|%s|%ld\n",ordinary,blank.len(),bounded,following,eof.len());
    free(ordinary); free(blank); free(bounded); free(following); free(eof);
    return 0;
}

